style.css:
body,
p,
h1, h2, h3, h4, h5, h6,
li,
label {
    color: #ffffff !important;
}

a {
    color: #ff4db8 !important;
}

a:hover {
    color: #66aaff !important;
}

button,
input[type="button"],
input[type="submit"],
input[type="reset"],
[role="button"] {
    background: linear-gradient(90deg, #e60087, #7b3fa1, #174fa3) !important;
    color: #ffffff !important;
    border: 1px solid #ff4db8 !important;
    border-radius: 8px !important;
}

button:hover,
input[type="button"]:hover,
input[type="submit"]:hover,
[role="button"]:hover {
    filter: brightness(1.25) !important;
}

input,
textarea,
select {
    background: #100b14 !important;
    color: #ffffff !important;
    border: 1px solid #7b3fa1 !important;
    border-radius: 6px !important;
}

::selection {
    background: #e60087 !important;
    color: #ffffff !important;
}

::-webkit-scrollbar {
    width: 10px;
}

::-webkit-scrollbar-track {
    background: #080808;
}

::-webkit-scrollbar-thumb {
    background: linear-gradient(#e60087, #7b3fa1, #174fa3);
    border-radius: 10px;
}

[role="menu"],
[role="dialog"],
[role="listbox"] {
    background: #100b14 !important;
    color: #ffffff !important;
    border-color: #7b3fa1 !important;
}
